<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useDraftGuard} from '../../composables/useDraftGuard.js'
import {notify} from '../../composables/feedback.js'
import FormField from '../../components/FormField.vue'
import DataTable from '../../components/DataTable.vue'
import {clone,columns,localInput,isoInput,takePlanSuggestion,requestKey} from '../strategies/operationUi.js'
const r=useIrrigation(),route=useRoute(),router=useRouter(),draft=ref(null),initial=ref(''),scheduled=ref(''),candidates=ref([]),selected=ref(null),busy=ref(false),failure=ref(''),errors=ref({}),assessment=ref(null),key=requestKey()
const creating=computed(()=>route.path.endsWith('/new')),source=computed(()=>(r.state.entities.Plan??[]).find(p=>p.planId===route.params.id))
watch(()=>[route.params.id,creating.value,r.state.ready],()=>{const suggestion=creating.value&&route.query.suggestion?takePlanSuggestion():null;draft.value=source.value?{...clone(source.value),steps:clone((r.state.entities.PlanStep??[]).filter(s=>s.planId===source.value.planId).sort((a,b)=>a.order-b.order))}:creating.value?{farmId:r.state.user?.farmId,name:'',status:'DRAFT',scheduledAt:null,steps:[],...suggestion}:null;scheduled.value=localInput(draft.value?.scheduledAt);candidates.value=(draft.value?.steps??[]).slice(0,5).map(step=>step.zoneId).filter(Boolean);initial.value=JSON.stringify({draft:draft.value,scheduled:scheduled.value});assessment.value=null},{immediate:true})
const guard=useDraftGuard(()=>JSON.stringify({draft:draft.value,scheduled:scheduled.value})!==initial.value),allowed=computed(()=>draft.value?.status==='DRAFT'&&r.can(creating.value?'PLAN_CREATE':'PLAN_UPDATE',source.value)),zones=computed(()=>(r.state.entities.IrrigationZone??[]).filter(z=>z.status==='ENABLED')),total=computed(()=>draft.value?.steps.reduce((n,s)=>n+Number(s.targetVolumeM3||0),0).toFixed(1)),run=computed(()=>(r.state.entities.IrrigationRun??[]).find(x=>x.planId===source.value?.planId))
const cols=columns([['order','顺序',95],['planStepId','步骤编号',205],['zoneId','分区名称'],['targetVolumeM3','目标 m³',180],['expectedFlowM3h','流量 m³/h',180],['maxDurationMin','上限 min',165]])
watch(()=>[JSON.stringify(draft.value),scheduled.value,r.state.revision],()=>{assessment.value=null})
function back(){router.push(route.query.from?.startsWith('/')?route.query.from:'/plans')}
function payload(){return {...clone(draft.value),scheduledAt:isoInput(scheduled.value),steps:draft.value.steps.map((s,i)=>({...clone(s),order:i+1}))}}
function chooseCandidate(event){const id=event.target.value;if(id&&!candidates.value.includes(id))candidates.value.push(id);event.target.value=''}
function add(){if(candidates.value.some(id=>draft.value.steps.some(s=>s.zoneId===id))){failure.value='分区已在步骤中，不能重复添加';return}for(const id of candidates.value){if(!draft.value.steps.some(s=>s.zoneId===id)){const z=zones.value.find(z=>z.zoneId===id);draft.value.steps.push({zoneId:id,order:draft.value.steps.length+1,targetVolumeM3:10,expectedFlowM3h:z.designFlowM3h,maxDurationMin:45})}}candidates.value=[]}
function move(delta){const i=draft.value.steps.findIndex(s=>s===selected.value);if(i<0||i+delta<0||i+delta>=draft.value.steps.length)return;const [s]=draft.value.steps.splice(i,1);draft.value.steps.splice(i+delta,0,s);draft.value.steps.forEach((s,i)=>s.order=i+1)}
function remove(){draft.value.steps=draft.value.steps.filter(s=>s!==selected.value);draft.value.steps.forEach((s,i)=>s.order=i+1);selected.value=null}
async function check(){busy.value=true;failure.value='';try{const p=payload(),snapshot=JSON.stringify(p),revision=r.state.revision,result=await r.query('resources',p);if(snapshot!==JSON.stringify(payload())||revision!==r.state.revision)throw new Error('编排或资源已变化，请重新检查');assessment.value=result;return result.ok}catch(e){failure.value=e.message;return false}finally{busy.value=false}}
async function save(){busy.value=true;failure.value='';errors.value={};try{const p=payload(),checked=await r.query('resources',p);assessment.value=checked;if(!checked.ok)throw new Error('资源检查未通过，请处理冲突后保存');const result=await r.commit(creating.value?'PLAN_CREATE':'PLAN_UPDATE',p,{expectedVersion:draft.value.version,clientRequestId:key(p)});const saved=(r.state.entities.Plan??[]).find(x=>x.planId===result.entityId);if(saved){draft.value={...clone(saved),steps:clone((r.state.entities.PlanStep??[]).filter(s=>s.planId===result.entityId).sort((a,b)=>a.order-b.order))}};initial.value=JSON.stringify({draft:draft.value,scheduled:scheduled.value});guard.markClean();notify('轮灌计划已保存');router.push({path:'/plans/'+result.entityId+'/edit',query:{from:route.query.from||'/plans'}})}catch(e){failure.value=e.message;errors.value=e.fieldErrors??{}}finally{busy.value=false}}
</script>
<template><div v-if="draft" class="page-stack plan-editor"><div class="editor-top"><button class="btn" @click="back">〈　返回</button><span v-if="!allowed" class="muted">{{draft.status==='DRAFT'?'无编辑权限':'此计划仅可查看'}}</span><button v-if="run" class="btn-link" @click="router.push({path:'/runs/'+run.runId,query:{from:route.fullPath}})">关联运行 {{run.runId}}</button></div><section class="panel plan-fields"><div class="form-grid"><FormField label="计划名称" :error="errors.name"><input v-model="draft.name" :readonly="!allowed||busy"/></FormField><FormField label="计划时间" :error="errors.scheduledAt"><input v-model="scheduled" type="datetime-local" step="1" :readonly="!allowed||busy"/></FormField></div><FormField class="candidate-field" label="候选分区" :error="errors.steps"><div class="candidate-bar"><div class="candidate-select"><span v-for="id in candidates" :key="id" class="zone-tag">{{zones.find(z=>z.zoneId===id)?.name}} <button :disabled="!allowed||busy" aria-label="移除候选分区" @click="candidates=candidates.filter(x=>x!==id)">×</button></span><select :disabled="!allowed||busy" aria-label="选择候选分区" @change="chooseCandidate"><option value=""></option><option v-for="z in zones" :key="z.zoneId" :value="z.zoneId" :disabled="draft.steps.some(s=>s.zoneId===z.zoneId)||candidates.includes(z.zoneId)">{{z.name}}</option></select></div><button class="btn btn-primary" :disabled="!allowed||!candidates.length" @click="add">添加</button></div></FormField></section><section class="panel step-panel"><DataTable :columns="cols" :rows="draft.steps" :row-key="s=>s.planStepId||s.zoneId" :selected-id="selected?.planStepId||selected?.zoneId" @row-click="selected=$event"><template #cell-planStepId="{value}">{{value||'保存后生成'}}</template><template #cell-zoneId="{value}">{{r.getIndex().byId.IrrigationZone.get(value)?.name||value}}</template><template #cell-targetVolumeM3="{row}"><input v-if="allowed" v-model.number="row.targetVolumeM3" class="cell-input" :readonly="busy" type="number" min="0.1" step="0.1" aria-label="目标水量"/><template v-else>{{Number(row.targetVolumeM3).toFixed(1)}}</template></template><template #cell-expectedFlowM3h="{row}"><input v-if="allowed" v-model.number="row.expectedFlowM3h" class="cell-input" :readonly="busy" type="number" min="0.1" step="0.1" aria-label="预计流量"/><template v-else>{{Number(row.expectedFlowM3h).toFixed(1)}}</template></template><template #cell-maxDurationMin="{row}"><input v-if="allowed" v-model.number="row.maxDurationMin" class="cell-input" :readonly="busy" type="number" min="1" aria-label="最长时长"/><template v-else>{{row.maxDurationMin}}</template></template></DataTable><div v-if="selected&&allowed" class="row-toolbar"><span>{{r.getIndex().byId.IrrigationZone.get(selected.zoneId)?.name}}</span><button class="btn btn-sm" @click="move(-1)">上移</button><button class="btn btn-sm" @click="move(1)">下移</button><button class="btn btn-sm" @click="remove">移除</button></div><div class="resource-footer"><div class="resource-status" :class="{ok:assessment?.ok}"><small>资源检查状态</small><strong>{{assessment?(assessment.ok?'检查通过':'存在资源冲突'):'待重新检查'}}</strong></div><div><small>轮灌步骤数</small><strong>{{draft.steps.length}}</strong></div><div><small>目标总量 m³</small><strong>{{total}}</strong></div><div class="resource-actions"><button class="btn" :disabled="busy" @click="check">检查资源</button><button class="btn btn-primary" :disabled="busy||!allowed" @click="save">{{busy?'处理中…':'保存'}}</button><button class="btn" :disabled="busy" @click="back">取消</button></div></div><p v-if="source&amp;&amp;draft.version!==source.version" class="error-text" role="status">来源版本已更新，当前输入已保留；保存时将检查版本冲突。</p><p v-if="failure" role="alert" class="error-text">{{failure}}</p><p v-for="(error,field) in errors" :key="field" class="error-text">{{field}}：{{error}}</p><div v-if="assessment&&!assessment.ok" class="conflicts"><p v-for="(c,i) in assessment.conflicts" :key="i" class="error-text">{{c.reason||c.message||c.code}} {{c.objectId||c.zoneId||''}}</p></div></section></div><section v-else class="panel empty-state">{{r.state.ready?'计划不存在或无权访问':'加载中…'}} <button class="btn" @click="back">返回</button></section></template>
<style scoped>.plan-editor{gap:12px}.editor-top{display:flex;gap:24px;align-items:center}.plan-fields{padding:20px 24px}.candidate-field{margin-top:18px}.candidate-bar{display:flex;gap:10px}.candidate-select{display:flex;align-items:center;gap:6px;flex:1;flex-wrap:wrap;border:1px solid #cbd9d7;border-radius:5px;padding:4px 8px;min-height:43px}.candidate-select select{width:auto;flex:1;min-width:110px;border:0;height:32px;min-height:32px}.zone-tag{display:inline-flex;align-items:center;background:#e6f2ed;border:1px solid #d5e8e0;padding:4px 9px;border-radius:4px;font-size:14px}.zone-tag button{border:0;background:none;cursor:pointer}.candidate-bar>.btn{min-width:95px}.step-panel{padding:16px 14px}.step-panel :deep(td){height:31px;padding-top:2px;padding-bottom:2px}.step-panel :deep(th){height:37px}.cell-input{border:1px solid transparent!important;background:transparent!important;text-align:center;width:100%;min-height:25px!important;height:25px!important;padding:0!important;border-radius:2px!important}.cell-input:hover,.cell-input:focus{border-color:#bed4ca!important;background:white!important}.resource-footer{display:flex;align-items:center;gap:42px;border-top:1px solid #e1e8e4;padding:18px 3px 4px;margin-top:6px}.resource-footer small{display:block;color:#526c6b}.resource-footer strong{display:block;font-size:30px;margin-top:7px}.resource-status{background:#fff5e3;border-radius:7px;padding:13px 25px;min-width:270px;color:#a45f08}.resource-status strong{font-size:18px}.resource-status.ok{background:#e6f6ed;color:#16765b}.resource-actions{margin-left:auto;display:flex;gap:12px}.resource-actions .btn{min-width:118px}.row-toolbar{display:flex;justify-content:flex-end;gap:8px;align-items:center;padding:8px;background:#f4f9f6}.conflicts{max-height:180px;overflow:auto}</style>
